import React, { useEffect, useState } from "react";
import Swal from "sweetalert2";
import { Lock, ShieldCheck } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
    DialogFooter,
} from "../ui/dialog";
import { Button } from "../ui/button";
import companyService from "../../services/company.service";

export const CompaniesFormModal = ({ company, onSuccess, trigger }) => {
  const [open, setOpen] = useState(false);
  const [name, setName] = useState("");
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});
  const isEditing = !!company;
  const isSystemCompany = !!company?.is_system;
  const setForm = ({ name }) => {
    setName(name);
  };

  useEffect(() => {
    if (open) {
      if (company) {
        setName(company.name);
      } else {
        setName("");
      }
    }
  }, [open, company]);
  const togglePermission = (permissionId) => {
    setForm((prev) => {
      const has = prev.permission_ids.includes(permissionId);
        return {
            ...prev,
            permission_ids: has
                ? prev.permission_ids.filter((id) => id !== permissionId)
                : [...prev.permission_ids, permissionId],
        };
    });
  };
  const toggleModule = (modulePermissions,allSelected) => {
    setForm((prev) => {
      const newPermissionIds = allSelected        ? prev.permission_ids.filter((id) => !modulePermissions.some((p) => p.id === id))        : [...prev.permission_ids, ...modulePermissions.filter((p) => !prev.permission_ids.includes(p.id)).map((p) => p.id)];
      return {
        ...prev,
        permission_ids: newPermissionIds,
      };
    });
  };
 const validate = () => {
    const newErrors = {};
    if (!name.trim()) {
      newErrors.name = "El nombre es requerido";
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };
  const handleSubmit = async () => {
    if (!validate()) return;
    setLoading(true);
    try {
      if (isEditing) {
        await companyService.updateCompany(company.id, { name });
        Swal.fire({
          icon: "success",
          title: "Empresa actualizada",
          confirmButtonColor: "#16a34a",
        });
      } else {
        await companyService.createCompany({ name });
        Swal.fire({
            icon: "success",
            title: "Empresa creada",
            confirmButtonColor: "#16a34a",
        });
      }
      setOpen(false);
      onSuccess();
    } catch (error) {
        Swal.fire({
            icon: "error",
            title: "Error",
            text: error.response?.data?.detail || "Intenta nuevamente",
            confirmButtonColor: "#16a34a",
        });
    } finally {
        setLoading(false);
    }
    };   
  return (
    <Dialog open={open} onOpenChange={setOpen}>
        <Button variant={isEditing ? "outline" : "default"} onClick={() => setOpen(true)}>
            {isEditing ? <Pencil size={16} /> : <Plus size={16} />}
            {isEditing ? "Editar" : "Crear empresa"}
        </Button>
        <DialogContent className="sm:max-w-md">
            <DialogHeader>
                <DialogTitle className="flex items-center gap-2">
                    <Lock className="w-5 h-5 text-green-600" />
                    {isEditing ? "Editar empresa" : "Nueva empresa"}
                </DialogTitle>
            </DialogHeader>
            <div className="grid gap-4 py-4">
                <div className="grid grid-cols-1 gap-2">
                    <label className="text-sm font-medium">Nombre</label>
                    <input
                        type="text"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        className="w-full border border-gray-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-green-500"
                        placeholder="Ej. Acme Corp"
                    />
                </div>
            </div>
            <DialogFooter>
                <Button variant="outline" onClick={() => setOpen(false)} disabled={loading}>
                    Cancelar
                </Button>
                <Button onClick={handleSubmit} disabled={loading}>
                    {isEditing ? "Guardar cambios" : "Crear empresa"}
                </Button>
            </DialogFooter>
        </DialogContent>
    </Dialog>
  );
}
export default CompaniesFormModal;
